        new(6, 2, "Wann beginnt sich fehlende Unterstützung für dich wie Alleingelassenwerden anzufühlen?", new OptionSeed[] { new("A", "Erwartungen ändern sich ohne Gespräch oder Unterstützung. Mit Veränderung komme ich klar, aber nicht, wenn ich sie allein auffangen oder erraten muss, was jetzt erwartet wird."), new("B", "Bei wichtigen Entscheidungen wird es schwer, Hilfe zu bekommen. Ich kann eigenständig arbeiten, aber blockierte Entscheidungen oder fehlende Orientierung lassen mich ohne Unterstützung dastehen."), new("C", "Ich höre nur Feedback, wenn etwas schiefgeht. Wenn es keine Ermutigung, Kalibrierung oder Rückmeldung gibt, bis ein Problem auftaucht, fühlt sich Unterstützung an, als wäre keine da."), new("D", "Koordination verschwindet, obwohl die Arbeit voneinander abhängt. Autonomie ist in Ordnung, aber verbundene Arbeit braucht trotzdem Kommunikation, Timing und gemeinsames Bewusstsein.") }),
        new(6, 3, "Wenn du unsicher bist, wie du weiterkommst, welche Art von Unterstützung hilft dir am meisten?", new OptionSeed[] { new("A", "Hilfe, das Ziel, die Rahmenbedingungen und das Wichtigste zu klären. Ich komme voran, sobald die Richtung klarer ist."), new("B", "Eine konkrete Entscheidung oder Empfehlung von jemandem mit Kontext. Ich möchte nicht blockiert bleiben, wenn jemand anderes den Weg freimachen kann."), new("C", "Ein Gespräch, um Optionen gemeinsam durchzudenken. Ich schätze Unterstützung, die mir beim Durchdenken hilft, statt mir nur eine Antwort zu geben."), new("D", "Raum, um erst selbst zu erkunden und dann zurückzumelden, was ich gelernt habe. Ich beziehe andere lieber nicht ein, bevor ich mir eine eigene Sicht gebildet habe.") }),
        new(6, 4, "Wann fühlt sich Verantwortung für deine Arbeit gesund an?", new OptionSeed[] { new("A", "Ich weiß, welche Entscheidungen meine sind. Klare Grenzen geben mir bei der Verantwortung ein sicheres Gefühl."), new("B", "Ich kann um Hilfe bitten, ohne dass es als mangelnde Kompetenz gesehen wird. Unterstützung sollte das Vertrauen nicht verringern."), new("C", "Andere bleiben so weit informiert, dass meine Arbeit nicht isoliert wird. Verantwortung sollte nicht heißen, zu verschwinden."), new("D", "Ich habe genug Freiheit, Abwägungen zu treffen, ohne für jeden Schritt eine Freigabe zu brauchen. Verantwortung sollte echte Befugnis mit sich bringen.") }),
        new(7, 1, "Welche Art von geplantem Status-Meeting fühlt sich für dich am nützlichsten an?", new OptionSeed[] { new("A", "Kurz, strukturiert und auf Blocker fokussiert — ich will hinterher wissen, was sich bewegt und was nicht, statt alles durchgesprochen zu haben."), new("B", "Diskussionsbasiert, mit Raum für Kontext — manchmal ist der Status selbst weniger nützlich als zu verstehen, warum die Dinge so sind, wie sie sind."), new("C", "Überwiegend asynchrone Updates, mit Meetings nur, wenn etwas wirklich live besprochen werden muss — der Standard sollte schriftlich sein, nicht geplant."), new("D", "Ein regelmäßiger Rhythmus, auch wenn es nicht immer viel zu besprechen gibt — die Beständigkeit selbst hat Wert, und ich habe lieber ein ruhiges Meeting, als die Gewohnheit zu verlieren.") }),
        new(7, 2, "Was ist die stärkste Rechtfertigung, jemanden mit einem ungeplanten Gespräch zu unterbrechen?", new OptionSeed[] { new("A", "Etwas ist wirklich blockiert und jede Stunde Warten hat reale Kosten. Ich unterbreche lieber, als die Arbeit stillstehen oder die Entscheidung länger offen bleiben zu lassen als nötig."), new("B", "Das Thema ist zu heikel oder schriftlich zu leicht misszuverstehen. Manches braucht Ton, Mimik und Reaktion in Echtzeit — keine Nachricht, die herumliegt und interpretiert wird."), new("C", "Der schriftliche Thread hat schon länger gedauert als ein kurzes Gespräch. Wenn asynchron aufhört, effizient zu sein, ist der Wechsel zu Echtzeit keine Unterbrechung — es ist die richtige Entscheidung."), new("D", "Ehrlich gesagt rechtfertigt es fast nichts von vornherein. Das meiste kann warten, und jemandes Fokus zu respektieren heißt für mich, die Person selbst entscheiden zu lassen, wann sie verfügbar ist, statt sie herauszureißen.") }),
        new(7, 3, "Wenn ein wiederkehrendes Meeting nur eines dieser Dinge garantieren könnte, welches würde es wert machen, es beizubehalten?", new OptionSeed[] { new("A", "Eine klare Agenda vorher und ein sichtbares Ergebnis, eine Entscheidung oder einen nächsten Schritt danach. Ohne diese zwei Dinge fällt es mir schwer, die Zeit zu rechtfertigen, egal wie oft wir uns treffen."), new("B", "Dass das Team regelmäßig tatsächlich im selben Raum ist. Ein Teil dessen, was Zusammenarbeit am Laufen hält, ist nicht Output — es ist Vertrautheit, Rhythmus und die Art von Verbindung, die in Aufgaben und Tickets nicht entsteht."), new("C", "Ein gemeinsames Bild davon, was sich verschiebt, was blockiert ist und was die Beteiligten voneinander brauchen. Fehlabstimmung kostet meist mehr als das Meeting selbst."), new("D", "Die echte Freiheit, es abzusagen, wenn es nicht gebraucht wird. Ein Meeting, das sich jedes Mal seinen Platz verdient, fühlt sich ganz anders an als eines, das nur stattfindet, weil es einmal angesetzt wurde.") }),
        new(7, 4, "Was lässt ein Meeting kräftezehrend oder unnötig wirken?", new OptionSeed[] { new("A", "Es kam keine klare Entscheidung, kein Ergebnis und kein nächster Schritt heraus — ich kann akzeptieren, dass ein Meeting schwer oder lang war, aber ich tue mich schwer damit, wenn ich nicht benennen kann, was dabei herausgekommen ist."), new("B", "Derselbe Kontext hätte schriftlich geteilt werden können, sodass die Beteiligten in ihrer eigenen Zeit hätten reagieren können — synchrone Zeit ist teuer, und ich merke, wenn sie nicht wirklich nötig ist."), new("C", "Zu viele Personen waren ohne klaren Grund dabei — das deutet entweder auf unklare Verantwortung hin oder auf die Gewohnheit, zu viele Menschen einzubeziehen, statt klar zu kommunizieren."), new("D", "Es hat mich aus fokussierter Arbeit gerissen, ohne genug Wert zu liefern, um die Kosten zu rechtfertigen — die Unterbrechung selbst ist das Problem, nicht nur der Inhalt des Meetings.") }),
        new(8, 1, "Wenn Arbeit dringend wird, welche Art von Kommunikation hilft dir am meisten?", new OptionSeed[] { new("A", "Eine ruhige, klare Aussage darüber, was gerade am wichtigsten ist und was warten kann — ich brauche keine inszenierte Dringlichkeit, ich brauche eine eindeutige Priorität, damit ich ohne Zögern handeln kann."), new("B", "Genug Kontext, um zu verstehen, warum es dringend ist und was tatsächlich auf dem Spiel steht — Dringlichkeit ohne Begründung macht es mir schwer, gute Entscheidungen über meine Reaktion zu treffen."), new("C", "Ein kurzer gemeinsamer Moment, um uns zu einigen, was wegfällt oder verschoben wird — ich kann schnell handeln, sobald wir ehrlich sind, was wir nicht mehr tun."), new("D", "Eine schriftliche Zusammenfassung, zu der ich zurückkehren kann — wenn es dringend ist, erzeugt ein Live-Gespräch Lärm, den ich im Kopf behalten muss. Schriftliche Erwartungen lassen mich konzentrieren, statt alles im Gedächtnis behalten zu müssen.") }),
        new(8, 2, "Deine Führungskraft spricht vor einer kritischen Deadline zum Team. Was würde dich tatsächlich am meisten motivieren?", new OptionSeed[] { new("A", "„Wir müssen liefern, sonst werden Köpfe rollen.\""), new("B", "„Wir sind jetzt nicht mehr in der Schule oder Uni, wir müssen liefern.\""), new("C", "„Ich finde das ehrlich einen spannenden Meilenstein. Sagt mir Bescheid, wenn euch irgendetwas blockiert.\""), new("D", "Nichts — die Deadline ist sichtbar, die Prioritäten sind klar. Eine Ansprache würde meist nur im Weg stehen.") }),
        new(8, 3, "Wenn eine Führungskraft oder ein Kollege Dringlichkeit auf eine Art kommuniziert, die dich stört, was tust du normalerweise?", new OptionSeed[] { new("A", "Ich spreche es direkt mit der Person an — nicht unbedingt im Moment, aber bald danach. Solche Muster sind es wert, benannt zu werden, auch wenn es unangenehm ist."), new("B", "Ich nehme es hin und konzentriere mich auf die Arbeit — ich lasse den Kommunikationsstil los und spreche ihn nicht an, außer er wird ein wiederholtes Muster, das das Team wirklich beeinträchtigt."), new("C", "Ich erwähne es jemandem, dem ich vertraue, aber nicht der Person direkt — manchmal reicht es, es laut auszusprechen, auch ohne Konfrontation."), new("D", "Es hängt von der Beziehung und der Häufigkeit ab — ein Einzelfall lässt sich meist loslassen, aber wenn es immer wieder passiert, sage ich etwas.") }),
        new(8, 4, "In einer Situation mit hohem Druck sagt dir jemand, dein Ton, deine Wortwahl oder dein Kommunikationsstil sei zu intensiv, zu direkt oder schwer aufzunehmen gewesen. Was ist dein Instinkt?", new OptionSeed[] { new("A", "Ich nehme es ernst und passe mich an — wenn meine Art zu kommunizieren es jemandem schwerer gemacht hat, klar zu denken oder gut zu handeln, liegt die Verantwortung bei mir, unabhängig vom Druck, unter dem wir beide standen."), new("B", "Ich möchte verstehen, was konkret schlecht angekommen ist, bevor ich etwas ändere — selbst unter Druck hilft es meist weder mir noch der anderen Person, etwas zu ändern, ohne verstanden zu haben, was schiefgelaufen ist."), new("C", "Ich erkenne die Reaktion an, sehe sie aber nicht automatisch als etwas, das ich beheben muss — manchmal spiegelt Intensität die Situation ehrlich wider, und ich finde, das kann man sagen, ohne sich dafür zu entschuldigen."), new("D", "Ich achte darauf, ob es ein Muster oder ein Einzelfall ist — Drucksituationen sind keine normalen Bedingungen, und eine einzelne Reaktion bedeutet nicht immer, dass ich meine Kommunikation grundsätzlich ändern muss.") }),
        new(9, 1, "Du bemerkst Spannung zwischen dir und einer Person, mit der du zusammenarbeitest. Was ist dir zuerst am wichtigsten?", new OptionSeed[] { new("A", "Verstehen, worin die Meinungsverschiedenheit eigentlich besteht — das Gefühl von Spannung ist nicht immer ein verlässliches Signal dafür, was wirklich falsch läuft, und ich möchte wissen, womit ich es tatsächlich zu tun habe, bevor ich darauf reagiere."), new("B", "Sicherstellen, dass es nicht das ganze Team betrifft — Spannung zwischen zwei Personen verändert leicht die Atmosphäre für alle, und ich fühle mich verantwortlich, die Spannung früh einzugrenzen, bevor sie übergreift."), new("C", "Uns beiden etwas Raum geben, bevor ich versuche, es anzusprechen — wenn Menschen noch mitten in der Spannung stecken, erzeugen Gespräche eher Reaktionen als Lösungen."), new("D", "Es direkt benennen, bevor es sich verhärten kann — je länger etwas Unausgesprochenes zwischen zwei Personen sitzt, desto mehr Gewicht bekommt es.") }),
        new(9, 2, "Wann sollte ein Thema eskaliert werden?", new OptionSeed[] { new("A", "Sobald echte Arbeit oder Koordination wirklich gefährdet ist — auf den richtigen Prozess zu warten, während etwas Reales kaputtgeht, fühlt sich an, als würde man Bequemlichkeit über Verantwortung stellen."), new("B", "Wenn das Thema eine Entscheidung oder Befugnis betrifft, die keine der Personen tatsächlich hat — manche Konflikte lassen sich nicht direkt lösen, weil die Beteiligten nicht die Macht dazu haben, und Eskalation ist dann keine Vermeidung, sondern der richtige Weg."), new("C", "Wenn sich dasselbe Muster ohne Besserung wiederholt — ein einzelner Vorfall rechtfertigt selten Eskalation, aber ein Muster, das niemand angeht, ist ein ganz anderes Problem."), new("D", "Nur wenn die Beteiligten es wirklich versucht haben und es allein nicht verantwortungsvoll lösen können — Eskalation sollte das letzte Mittel sein, keine Abkürzung um ein schwieriges Gespräch herum.") }),
        new(9, 3, "Wenn ein schwieriges Gespräch nötig ist, was soll dabei vor allem herauskommen?", new OptionSeed[] { new("A", "Eine klare Entscheidung oder Lösung — schwere Gespräche kann ich gut führen, wenn sie mit etwas Konkretem enden. Mehrdeutigkeit nach einem schwierigen Austausch ist für mich schwerer als das Gespräch selbst."), new("B", "Gegenseitiges Verständnis dafür, wie jede Person es sieht — ich brauche nicht immer Einigung, aber ich muss spüren, dass beide Sichtweisen wirklich gehört wurden, bevor wir weitermachen."), new("C", "Dass die Beziehung intakt und arbeitsfähig bleibt — das Ergebnis zählt, aber nicht mehr als dass beide danach zusammenarbeiten können, ohne dass es über allem hängt."), new("D", "Dass beide einen Teil der Verantwortung übernehmen — Gespräche sind für mich ehrlicher, wenn niemand nur gibt oder nur nimmt. Geteilte Verantwortung verändert die Dynamik völlig.") }),
        new(9, 4, "Wenn sich Spannung oder Konflikt zwischen dir und einer Person, mit der du zusammenarbeitest, nicht von selbst löst, würdest du dir jemanden zur Moderation wünschen, und wer sollte das sein?", new OptionSeed[] { new("A", "Ja — eine neutrale Person auf Augenhöhe, die uns beide kennt und genug Kontext hat, um zu helfen, ohne Partei zu ergreifen."), new("B", "Ja — eine Führungskraft oder jemand mit genug Befugnis, um die Sache voranzubringen, wenn das Gespräch ins Stocken gerät."), new("C", "Nur wenn beide zustimmen — eine Moderation, die einer Seite aufgezwungen wird, macht es meist schlimmer, nicht besser."), new("D", "Nein — eine dritte Person hinzuzuziehen verändert die Dynamik auf eine schwer umkehrbare Weise. Ich löse es lieber direkt, auch wenn es länger dauert.") }),
        new(9, 5, "Wenn Spannung oder Konflikt in einem Team auftritt, was glaubst du, wie sich das löst?", new OptionSeed[] { new("A", "Es braucht aktives Eingreifen — sich selbst überlassen, bessert sich Spannung selten; meist verhärtet sie sich zu etwas, das später schwerer anzugehen ist."), new("B", "Es hängt von den Beteiligten ab — nicht alle verarbeiten Konflikt gleich, und anzunehmen, alle bräuchten dieselbe Art von Gespräch, Raum oder Ritual, erzeugt meist eigene Reibung."), new("C", "Oft löst es sich von selbst, wenn Menschen genug Raum und Zeit bekommen — zu frühes Eingreifen kann dazu führen, dass sie sich eher verwaltet als vertraut fühlen."), new("D", "Es lässt sich verlässlicher lösen, wenn das Team regelmäßige Praktiken hat, um Spannungen früh und sicher anzusprechen — nicht erst, wenn etwas zerbricht. Ohne solche Gewohnheiten warten Menschen zu lange oder vermeiden es ganz.") }),
        new(9, 6, "Du bist in einer Führungsrolle, und ein Teammitglied kommt zu dir und sagt, es sei in einem Konflikt mit jemandem im Team. Was ist dein Instinkt?", new OptionSeed[] { new("A", "Ich höre zuerst zu und frage, was die beiden schon versucht haben — ich möchte die Situation verstehen, bevor ich etwas tue, und sie dabei unterstützen, es direkt zu lösen, wenn das noch möglich ist."), new("B", "Ich biete an, ein Gespräch zu moderieren oder eine Moderation zwischen beiden zu organisieren — sie auf strukturierte Weise zusammenzubringen fühlt sich nützlicher an, als jede Seite getrennt zu behandeln."), new("C", "Ich spreche separat mit der anderen Person, um ihre Sicht zu hören, bevor ich etwas entscheide — eine Schilderung ist nie das ganze Bild."), new("D", "Ich schätze ab, ob es das ganze Team betrifft, bevor ich entscheide, wie ich reagiere — ein Konflikt zwischen zwei Personen ist manchmal ein Symptom für etwas Größeres, und das möchte ich verstehen, bevor ich mich nur auf die beiden konzentriere.") }),
        new(10, 1, "Was motiviert dich bei deiner Arbeit am meisten?", new OptionSeed[] { new("A", "Das Handwerk selbst — ich finde echte Zufriedenheit darin, Dinge gut zu bauen, schwere Probleme zu lösen und Abläufe zu verbessern. Die Arbeit ist ihre eigene Belohnung."), new("B", "Den Zweck verstehen — ich muss wissen, warum etwas wichtig ist. Meine Motivation sinkt deutlich, wenn ich die Arbeit nicht mit einem sinnvollen Ergebnis verbinden kann."), new("C", "Verantwortung und Vertrauen — echte Verantwortung und die Freiheit, Entscheidungen zu treffen, machen Arbeit für mich lohnenswert."), new("D", "Die Menschen und Beziehungen — das Team, die Zusammenarbeit, die gemeinsame Erfahrung, etwas zusammen aufzubauen, zählen für mich mehr als die Arbeit selbst.") }),
        new(10, 2, "Wovon möchtest du in deiner Arbeit mehr?", new OptionSeed[] { new("A", "Tiefe Fokuszeit — ununterbrochene Phasen, in denen ich wirklich denken kann, statt nur auf das zu reagieren, was am dringendsten ist."), new("B", "Klarere Prioritäten — nicht mehr Informationen, nur ein ehrlicheres Signal, was gerade wirklich am wichtigsten ist."), new("C", "Bessere Zusammenarbeit und besseres Feedback — Arbeit, die echten Austausch bedeutet, nicht nur parallele Anstrengung mit gelegentlichen Updates."), new("D", "Mehr Verantwortung und Entscheidungsspielraum — ich möchte mit dem ganzen Problem betraut werden, nicht nur mit der Umsetzung der Lösung von jemand anderem.") }),
        new(10, 3, "Welche Art von Anerkennung fühlt sich für dich am bedeutsamsten an?", new OptionSeed[] { new("A", "Jemand bemerkt die Qualität und Sorgfalt in meiner Arbeit — nicht nur, dass sie erledigt ist, sondern dass die Art, wie sie gemacht wurde, jemandem wirklich etwas bedeutet hat."), new("B", "Jemand betraut mich mit mehr Verantwortung oder einem schwereren Problem — Anerkennung über Verantwortung fühlt sich für mich echter an als Worte."), new("C", "Jemand würdigt den Einsatz während einer schwierigen oder stressigen Phase — gesehen zu werden, wenn es hart ist, bedeutet mir mehr als gelobt zu werden, wenn es leicht ist."), new("D", "Jemand verbindet meine Arbeit mit einem größeren Ergebnis — es ist für mich bedeutsam, wenn ich sehen kann, wie das, was ich getan habe, etwas Wichtiges tatsächlich bewegt hat.") }),
        new(10, 4, "Was zehrt bei der Arbeit am meisten an dir?", new OptionSeed[] { new("A", "Vermiedener Konflikt oder indirekte Kommunikation — wenn Probleme sichtbar sind, aber niemand sie benennt, wird es zermürbend, in diesem Schweigen zu arbeiten."), new("B", "Überflüssige Prozesse, unnötige Meetings oder Aufwand ohne Ergebnis — mit Struktur komme ich klar, solange sie einem Zweck dient, aber Prozess, der nur sich selbst dient, zehrt mit der Zeit an meiner Motivation."), new("C", "Arbeit, die von jedem sinnvollen Ergebnis abgekoppelt wirkt — ich kann harte oder langweilige Arbeit durchziehen, wenn ich verstehe, warum sie zählt. Wenn ich das nicht sehe, fühlt sich die Anstrengung hohl an."), new("D", "Das Gefühl, unterfordert oder unsichtbar zu sein — wenn mein Urteil, meine Fähigkeiten oder mein Beitrag konsequent übersehen oder nicht eingeholt werden, ist das auf eine schwer benennbare, aber kaum zu ignorierende Weise erschöpfend.") }),
        new(10, 5, "Was lässt einen guten Arbeitstag am Ende am ehesten wie gut genutzte Zeit wirken?", new OptionSeed[] { new("A", "Ich habe sichtbaren Fortschritt bei etwas gemacht, das wirklich zählt — keine Beschäftigungstherapie, keine Vorbereitung für künftige Arbeit, sondern echte Bewegung bei etwas mit Gewicht."), new("B", "Ich habe jemandem geholfen oder etwas beseitigt, das ihn blockiert hat — zu wissen, dass der Tag die Arbeit von jemand anderem leichter oder besser gemacht hat, reicht mir."), new("C", "Ich habe etwas verstanden, das ich vorher nicht verstanden habe — ein Tag, an dem sich mein mentales Modell des Problems, des Systems oder der Menschen verbessert hat, fühlt sich gut genutzt an, auch ohne sichtbaren Output."), new("D", "Ich habe Dinge besser hinterlassen, als ich sie vorgefunden habe — eine sauberere Codebasis, ein klarerer Prozess, eine gelöste Spannung. Schrittweise Verbesserung in die richtige Richtung ist auf eine stille Weise befriedigend, die großer sichtbarer Fortschritt manchmal nicht ist.") }),
    };

