    internal static readonly InsightSeed[] Insights =
    {
        new("upfront_clarity_need", "Du brauchst klare Ziele, Erwartungen und einen klaren Qualitätsanspruch, bevor du dich festlegst. Ohne diese Klarheit fällt es dir schwer, mit einem sicheren Gefühl loszulegen."),
        new("clarity_via_written_context", "Du verlässt dich mehr auf Schriftliches als auf Erinnerung oder Gespräche. Entscheidungen, die nur in jemandes Kopf existieren oder einmal im Meeting gefallen sind, geben dir wenig Sicherheit."),
        new("clarity_via_artifact_context", "Echte Beispiele sagen dir mehr als Beschreibungen. Lieber schaust du dir bestehenden Code, ein Ticket oder einen vorhandenen Standard an, als eine Erklärung zu lesen, wie etwas funktioniert."),
        new("learning_by_doing", "Du verstehst Dinge, indem du sie tust. Ein kleines echtes Experiment sagt dir mehr als noch so viel Lesen oder Reden vorab."),
        new("ambiguity_tolerance", "Es macht dir nichts aus, anzufangen, bevor alles geklärt ist. Dass noch nicht alle Antworten da sind, hält dich nicht auf — du fängst lieber an und verfeinerst unterwegs, als auf vollständige Gewissheit zu warten."),
        new("explicit_alignment_need", "Du brauchst eine ausdrückliche Einigung, bevor es weitergeht. Auf Basis von Annahmen zu handeln, die niemand wirklich bestätigt hat, ist dir unangenehm — du klärst und stimmst dich lieber ab, als später festzustellen, dass ihr nicht dasselbe meint."),
        new("social_context_need", "Kontext über Menschen ist dir genauso wichtig wie Kontext über die Arbeit. Zu verstehen, wer was macht, wie das Team funktioniert und welche Dynamiken es gibt, hilft dir, bessere Entscheidungen zu treffen und dich schneller einzufinden."),
        new("visibility_preference", "Du magst es, wenn Arbeit sichtbar ist, während sie passiert. Zu sehen, was sich bewegt, was blockiert ist und woran andere arbeiten, hilft dir, dich zu koordinieren, und gibt dir die Sicherheit, dass das Bild stimmt."),
        new("verbal_alignment_preference", "Ein direktes Gespräch funktioniert für dich besser als schriftlicher Austausch. Im Gespräch kannst du prüfen, ob du etwas richtig verstanden hast, das Ungesagtes mitbekommen und genau die Nachfrage stellen, die den eigentlichen Punkt freilegt — das schafft ein Nachrichten-Thread selten."),
        new("scheduled_communication_preference", "Mit einem vorhersehbaren Kommunikationsrhythmus arbeitest du besser. Zu wissen, wann Abstimmung stattfindet, lässt dich vorbereiten — und die Verlässlichkeit selbst hat einen Wert, auch wenn es gerade wenig zu besprechen gibt."),
        new("immediate_alignment_preference", "Wenn etwas geklärt werden muss, kümmerst du dich lieber sofort darum, als zu warten. Eine Fehlabstimmung oder einen Blocker bis zum nächsten geplanten Moment liegen zu lassen, bremst dich unnötig aus."),
        new("focus_protection", "Ungestörte Fokuszeit ist dir wichtig. Unterbrechungen, unnötige Meetings und ständige Kontextwechsel haben einen echten Preis — und du merkst, wenn dieser Preis sich nicht durch das auszahlt, was dabei herauskommt."),
        new("visible_result_need", "Du brauchst das Gefühl, dass aus deinem Einsatz etwas Konkretes entsteht. Ein Meeting ohne Entscheidung, ein Gespräch ohne Ergebnis oder ein Tag ohne echten Fortschritt ist für dich schwer zu rechtfertigen — erst das Ergebnis lässt die Zeit gut investiert wirken."),
        new("relational_connection_need", "Die Beziehungen bei der Arbeit zählen für dich unabhängig vom Ergebnis. Regelmäßiger Kontakt, Vertrautheit und der gemeinsame Rhythmus sind dir die Zeit wert — nicht alles muss ein Ergebnis abwerfen, um sich zu lohnen."),
        new("iteration_preference", "Feste Zyklen funktionieren gut für dich — ein vorhersehbarer Takt mit klaren Momenten zum Planen, Liefern und Verbessern. Der Rhythmus selbst hilft dir, dein Bestes zu geben."),
        new("flow_preference", "Du nimmst dir die nächste Aufgabe lieber aus einem klaren Backlog und hältst die Arbeit kontinuierlich in Bewegung. Auf den nächsten Sprint zu warten oder mehr zu planen, als du zum Starten brauchst, erzeugt eine Reibung, auf die du gut verzichten kannst."),
        new("upfront_planning_preference", "Du willst das vollständige Bild, bevor du mit der Umsetzung beginnst. Den Umfang, die Abhängigkeiten und die Risiken zu kennen, lässt dich sicher vorankommen, statt unterwegs auf Überraschungen zu stoßen."),
        new("adaptive_planning_preference", "Du beginnst lieber mit einer groben Richtung und verfeinerst den Plan, während du dazulernst, statt dich auf einen vollständigen Plan festzulegen, bevor du das Problem verstanden hast. Zu viel Planung im Vorfeld erzeugt eine falsche Sicherheit, die nur im Weg steht."),
        new("evidence_based_planning_preference", "Wenn etwas unsicher oder riskant ist, machst du lieber ein kleines Experiment, als dich auf einen Plan aus ungetesteten Annahmen festzulegen. Was du aus einem echten Test lernst, ist mehr wert als jede Überlegung, die du nicht überprüft hast."),
        new("participatory_decision_preference", "Wenn eine Entscheidung deine Arbeit betrifft, erwartest du, Teil davon zu sein, bevor sie fällt — nicht erst danach davon zu erfahren. Im Nachhinein informiert zu werden, wenn die Richtung schon feststeht, fühlt sich nicht nach Einbindung an."),
        new("planning_boundary_protection", "Du brauchst einen Plan, der vor ständiger Unterbrechung geschützt ist. Änderungen zu sammeln und am nächsten Planungspunkt zu behandeln — statt mitten im Fluss — ist für dich der Weg, produktiv zu bleiben und Zusagen zu machen, die etwas bedeuten."),
        new("capacity_protection", "Wenn etwas Neues dazukommt, muss etwas anderes weichen. Du erwartest, dass dieser Tausch ausdrücklich gemacht wird — immer mehr Arbeit auf bestehende Zusagen zu packen, ohne zu benennen, was dafür liegen bleibt, ist für dich nicht in Ordnung."),
        new("sustainable_pace_preference", "Ein nachhaltiges Arbeitstempo ist dir wichtig. Du wehrst dich gegen ausufernden Umfang und Überlastung — nicht, weil du harte Arbeit scheust, sondern weil du weißt, dass Ausbrennen niemandem hilft."),
        new("tradeoff_visibility", "Wenn eine Entscheidung fällt, willst du wissen, was bedacht wurde und was dafür aufgegeben wird. Eine Entscheidung ohne sichtbare Abwägungen wirkt für dich unvollständig — du musst den Preis verstehen, nicht nur das Ergebnis."),
        new("change_tolerance", "Änderungen an Umfang oder Richtung kannst du ohne viel Reibung aufnehmen. Wenn etwas Wichtiges aufkommt, reagierst du lieber darauf, als den ursprünglichen Plan um seiner selbst willen zu verteidigen."),
        new("ownership_boundary_clarity", "Du musst wissen, wer wofür verantwortlich ist. Unklare Grenzen bei Entscheidungen und Zuständigkeiten führen dazu, dass Dinge liegen bleiben oder doppelt gemacht werden — und dass unklar ist, an wen man sich wenden soll, wenn etwas geklärt werden muss."),
        new("autonomous_pace_preference", "Du bestimmst dein eigenes Tempo. Wiederholte Check-ins, die nichts ändern und der Arbeit nicht helfen, fühlen sich eher nach Überwachung als nach Unterstützung an — und das untergräbt mit der Zeit das Vertrauen."),
        new("autonomous_execution_preference", "Sobald du für etwas verantwortlich bist, willst du auch über das Wie entscheiden. Detaillierte Vorgaben zu Arbeit, die ohnehin dir gehört, signalisieren, dass deinem Urteil nicht vertraut wird — und das lässt die Verantwortung hohl wirken."),
        new("support_over_control_preference", "Mit Aufsicht kommst du gut zurecht, wenn sie dich wirklich unterstützt. Womit du nicht zurechtkommst, ist Aufsicht aus Angst oder dem Bedürfnis, jeden Schritt freizugeben — das ist Kontrolle, nicht Unterstützung, und den Unterschied spürt man."),
        new("unblocking_support_need", "Du musst Hilfe bekommen können, wenn du feststeckst. Wenn du bei wichtigen Entscheidungen keine Orientierung bekommst oder Unterstützung dauerhaft nicht verfügbar ist, stehst du ohne Rückhalt da, und das untergräbt deine Verantwortung."),
        new("proactive_feedback_need", "Du brauchst mehr als Schweigen, das nur von Problemen unterbrochen wird. Laufende Signale — Orientierung, Ermutigung, echter Austausch — helfen dir, orientiert und bei der Sache zu bleiben. Ohne diese Rückmeldung fühlt es sich bald an, als würdest du ganz für dich allein arbeiten."),
        new("directive_support_preference", "Wenn du feststeckst, willst du eine konkrete Antwort oder Empfehlung — kein gemeinsames Durchdenken der Optionen. Der Wert von Unterstützung ist in dem Moment, wieder freizukommen, nicht, dass jemand mit dir mitdenkt."),
        new("help_seeking_safety_need", "Du musst um Hilfe bitten können, ohne dass es gegen dich zählt. Wenn Hilfesuchen als Schwäche oder mangelnde Kompetenz gilt, hören Menschen auf zu fragen — und genau dann wachsen Probleme leise weiter, bis sie nicht mehr zu übersehen sind."),
        new("autonomous_problem_resolution", "Dein Instinkt ist, Probleme erst selbst zu lösen, bevor du andere einbeziehst. Andere zu früh einzubeziehen erzeugt Lärm und Abhängigkeit — und die meisten Dinge lassen sich ohne Eskalation lösen, wenn du es erst ernsthaft selbst versuchst."),
        new("risk_transparency_need", "Du sprichst ein Risiko lieber früh an, als es zur Überraschung werden zu lassen. Probleme, die zurückgehalten werden, bis sie dringend sind, sind schwerer zu lösen — und du hältst dich an denselben Maßstab, den du von anderen erwartest."),
        new("pragmatic_completion_preference", "Für dich ist Arbeit fertig, wenn das Kernproblem zuverlässig gelöst ist. Folgepunkte und Sonderfälle sind wichtig, aber sie sollten eine Übergabe nicht immer blockieren — stetiger Fortschritt ist mehr wert als das Warten auf Perfektion."),
        new("external_validation_need", "Ein zweites Augenpaar macht die Arbeit für dich belastbarer. Du vertraust einer Übergabe mehr, wenn jemand anderes sie geprüft hat — nicht, weil du an deinem eigenen Urteil zweifelst, sondern weil eine zweite Sicht der Weg ist, das zu erkennen, was du selbst nicht siehst."),
        new("impact_calibration_preference", "Wenn etwas schiefgeht, schätzt du erst ein, bevor du reagierst. Die tatsächliche Schwere und Wirkung zu verstehen — nicht nur den ersten Schreck — führt zu angemesseneren, nützlicheren Reaktionen."),
        new("root_cause_orientation", "Eine Lösung, die nicht die Ursache angeht, ist für dich keine echte Lösung. Du willst verstehen, warum etwas passiert ist — das Muster, den tieferen Grund — und damit verhindern, dass dasselbe Problem wiederkommt."),
        new("quality_protection_preference", "Du schützt den Qualitätsanspruch, auch wenn Termine drängen. Manche Risiken sind es nicht wert, eingegangen zu werden, egal wie groß der Druck ist — und du stellst lieber Umfang oder Zeitplan infrage, als etwas auszuliefern, das Wichtiges aufs Spiel setzt."),
        new("accountability_preference", "Wenn in deiner Arbeit ein Problem auftaucht, ist dein Instinkt, dazu zu stehen und es zu beheben. Zu erklären, warum es passiert ist, oder zu hinterfragen, ob es überhaupt dein Problem ist, kommt danach — zuerst zählt, es in Ordnung zu bringen."),
        new("critical_feedback_validation", "Du hältst nicht jede Kritik automatisch für berechtigt. Bevor du ein Bedenken annimmst, prüfst du, ob wirklich eine echte Lücke dahintersteckt — das Bedenken selbst kann es wert sein, hinterfragt zu werden."),
        new("feedback_content_primacy_giving", "Wenn du Feedback gibst, zählt vor allem, dass dein Anliegen zutreffend und nützlich ist — nicht, wie angenehm es zu hören ist. Ein berechtigter Punkt sollte nicht abgetan werden, nur weil er schwer zu hören war."),
        new("feedback_delivery_awareness_giving", "Feedback wirkt nur, wenn die andere Person es auch nutzen kann. Wenn du Feedback gibst, ist das Wie genauso wichtig wie das Was — inhaltlich richtig zu liegen bringt nichts, wenn die Art der Übermittlung verhindert, dass es ankommt."),
        new("feedback_content_primacy_receiving", "Wenn du Feedback bekommst, achtest du auf den Inhalt — auch wenn die Übermittlung ungeschickt oder hart war. Du lässt nicht zu, dass der Stil dir im Weg steht, einen vielleicht berechtigten Punkt zu hören."),
        new("feedback_delivery_awareness_receiving", "Wie Feedback übermittelt wird, beeinflusst, ob du es wirklich verarbeiten kannst. Wenn die Art unpassend oder unklar ist, fällt es dir deutlich schwerer, dich mit dem Anliegen zu befassen — das ist keine Vorliebe, sondern wie du funktionierst."),
        new("communication_norm_alignment", "Wenn ein Feedback- oder Kommunikationsmuster Reibung erzeugt, willst du dich darauf einigen, wie es künftig laufen soll — nicht nur den einzelnen Vorfall klären und weitermachen. Das Muster selbst ist es, das geändert werden muss."),
        new("private_feedback_preference", "Dein Standard ist, Bedenken unter vier Augen anzusprechen. Ein Problem in einen öffentlichen oder Gruppenkontext zu bringen, bevor du es einzeln zu klären versucht hast, ist für dich das letzte Mittel — und oft der falsche erste Schritt."),
        new("dignity_in_feedback_need", "Wenn Feedback vor anderen geäußert wird, ist dir enorm wichtig, wie damit umgegangen wird. Öffentlich kritisiert oder bloßgestellt zu werden, macht es schwer, sich mit dem Anliegen selbst zu befassen — Würde ist eine Voraussetzung, keine Vorliebe."),
        new("relational_repair_need", "Nach einem schwierigen Austausch muss für dich die Beziehung wieder in Ordnung kommen — getrennt davon, ob die Sache gelöst ist. Ein klärendes Gespräch danach, das anerkennt, was passiert ist, und einen Neustart ermöglicht, ist es, was dich weitermachen lässt, ohne dass es über allem hängt."),
        new("calm_urgency_preference", "Wenn es dringend wird, brauchst du eine ruhige und klare Kommunikation — kein Drama. Gespielter Stress oder Aufregung hilft dir nicht, schneller zu werden; eine eindeutige Aussage darüber, was am wichtigsten ist, schon."),
        new("pressure_driven_motivation", "Wenn viel auf dem Spiel steht und du direkt verantwortlich bist, läufst du erst richtig zur Form auf. Wenn der Druck echt ist und auch so benannt wird, reagierst du darauf — diese Art von Dringlichkeit ist für dich ein Antrieb, kein bloßer Lärm."),
        new("positive_motivation_preference", "Ermutigung und Sinn wirken bei dir besser als Druck. Wenn jemand die Arbeit als spannend oder bedeutsam darstellt und klarmacht, dass er hinter dir steht, bewegt dich das — nicht Konsequenzen oder Dringlichkeit."),
        new("autonomous_motivation", "Du brauchst keine Motivation von außen. Aufmunternde Reden und Deadline-Appelle stehen dir meist eher im Weg — du weißt schon, was zu tun ist, und treibst dich selbst an. Was du brauchst, ist Klarheit und Freiraum, kein Anschieben."),
        new("pressure_recognition_need", "Anerkennung bedeutet dir am meisten, wenn es schwer ist. Während einer angespannten oder schwierigen Phase gesehen zu werden, zählt mehr als Routinelob, wenn alles glattläuft — dann kommt Anerkennung wirklich an."),
        new("direct_conflict_approach", "Wenn es Reibung gibt, sprichst du sie direkt mit der Person an — auch wenn es unangenehm ist. Sie früh zu benennen, bevor sie sich verhärten kann, ist besser, als sie zu umgehen oder darauf zu warten, dass sie sich von selbst löst."),
        new("communication_friction_tolerance", "Unangenehme Kommunikationsstile kannst du aushalten, ohne sie jedes Mal ansprechen zu müssen. Dass dich etwas persönlich stört, ist für dich noch kein Grund zu eskalieren — du lässt Dinge auf sich beruhen, solange sie nichts Wichtiges wirklich beeinträchtigen."),
        new("team_impact_orientation", "Deine Schwelle, bei Reibung zu handeln, ist die Wirkung aufs Team, nicht dein persönliches Unbehagen. Wie sich etwas für dich anfühlt, ist nicht der Maßstab — entscheidend ist, ob es das Team oder die Arbeit beeinträchtigt."),
        new("conflict_avoidance_tendency", "Ein unangenehmes Verhaltensmuster direkt anzusprechen, ist nicht dein erster Impuls. Du brauchst erst Zeit und Abstand, um es zu verarbeiten, bevor du entscheiden kannst, ob und wie du handelst — ohne diesen Abstand geht das Ansprechen meist nicht gut aus."),
        new("indirect_conflict_processing", "Wenn dich zwischenmenschlich etwas stört, ist dein Instinkt, es erst mit jemandem zu besprechen, dem du vertraust — nicht, es gleich direkt mit der betroffenen Person anzusprechen. Es laut auszusprechen hilft dir herauszufinden, was du eigentlich denkst."),
        new("tension_deescalation_preference", "Du glaubst, dass angespannte Gespräche selten gut laufen, solange die Spannung noch hoch ist. Beiden Beteiligten Zeit zu geben, sich zu beruhigen, führt zu besseren Gesprächen — mitten in der Spannung zu reden erzeugt eher Reaktionen als Lösungen."),
        new("issue_escalation_preference", "Eskalation ist für dich ein legitimes Mittel, kein letzter Ausweg. Es ist richtig, jemanden mit mehr Befugnis hinzuzuziehen, wenn ein Problem das übersteigt, was die Beteiligten lösen können — wegen Umfang, fehlender Befugnis oder eines wiederkehrenden Musters. Das ist kein Versagen."),
        new("mutual_understanding_need", "In schwierigen Gesprächen ist dir am wichtigsten, dass beide Sichtweisen wirklich gehört werden — nicht nur, dass eine Entscheidung fällt. Du brauchst das Gefühl, gehört worden zu sein, bevor du weitermachen kannst, auch wenn keine klare Einigung zustande kommt."),
        new("shared_accountability_preference", "Schwierige Gespräche fühlen sich für dich ehrlicher an, wenn beide einen Teil übernehmen. Dass eine Person das Problem benennt und die andere die ganze Verantwortung trägt, passt für dich nicht — echte Verantwortung ist meistens geteilt."),
        new("facilitation_openness", "Strukturierte Moderation siehst du als echte Option, um Konflikte zu lösen — nicht als Zeichen, dass etwas gründlich schiefgelaufen ist. Ob du teilnimmst oder selbst führst: eine dritte Person hinzuzuziehen, die das Gespräch strukturiert, kann der wirksamste Weg nach vorn sein."),
        new("proactive_conflict_culture_preference", "Du glaubst, Konflikte sind leichter zu handhaben, wenn Teams sich schon Gewohnheiten dafür schaffen, bevor etwas zerbricht. Retrospektiven, in denen es auch darum geht, wie es den Menschen geht, Regeln fürs Ansprechen von Bedenken, regelmäßige Check-ins, in denen Spannung benannt werden kann — das macht ein Team sicher genug, um ehrlich zu sein."),
        new("craft_intrinsic_motivation", "Die Arbeit selbst treibt dich an. Etwas gut zu bauen, ein schweres Problem zu lösen, die Details richtig hinzubekommen — das ist für sich befriedigend, unabhängig davon, ob es jemand bemerkt oder wofür es am Ende gut ist."),
        new("purpose_driven_motivation", "Du musst verstehen, warum das, was du tust, wichtig ist. Wenn der Zweck klar ist und die Arbeit mit etwas Sinnvollem verbunden ist, bist du voll dabei. Wenn du diese Verbindung nicht siehst, ist Motivation wirklich schwerer zu halten."),
        new("autonomy_driven_motivation", "Echte Verantwortung ist es, die Arbeit für dich lohnend macht. Mit einem Problem betraut zu werden und die Freiheit zu haben, es auf deine Weise zu lösen, gibt dir Energie. Ohne das fängt selbst interessante Arbeit an, hohl zu wirken."),
        new("relational_driven_motivation", "Die Menschen sind es, die die Arbeit für dich wertvoll machen. Das Team, die gemeinsame Erfahrung, etwas zusammen aufzubauen, die Beziehungen, die dabei entstehen — daraus ziehst du mehr Energie als aus der Arbeit selbst."),
        new("learning_orientation", "Ein Tag, an dem du etwas besser verstehst, fühlt sich gut genutzt an — auch ohne sichtbares Ergebnis. Bessere Denkmodelle, eine neue Einsicht, ein klareres Bild vom System oder von den Menschen: Das ist dir einen Tag wert."),
        new("improvement_satisfaction", "Du findest eine stille Zufriedenheit darin, Dinge besser zu hinterlassen, als du sie vorgefunden hast. Eine sauberere Codebasis, ein klarerer Prozess, eine aufgelöste Spannung — schrittweise Verbesserung in die richtige Richtung reicht dir, ohne dass es ein großes sichtbares Ergebnis oder Anerkennung braucht."),
        new("delivery_reflection_priority", "Das Wichtigste, was ein Team betrachten kann, ist für dich, ob es verlässlich vorankommt und liefert. Prozess, Planung und der Arbeitsfluss verdienen eigene Reflexionszeit — die Arbeitsfähigkeit ist das Fundament, auf dem alles andere steht."),
        new("technical_reflection_priority", "Du findest, technische Qualität verdient einen Platz, wenn ein Team reflektiert. Vorfälle, Wartbarkeit und Solidität sind nicht zweitrangig gegenüber der Liefergeschwindigkeit — sie entscheiden darüber, ob das Team überhaupt weiter liefern kann."),
        new("interpersonal_reflection_priority", "Du findest, Muster der Zusammenarbeit und Kommunikationsgewohnheiten lohnen die Betrachtung — auch wenn sie weniger dringend wirken als die Lieferung. Bleiben sie unbeachtet, taucht die Reibung hier früher oder später in der Arbeit auf."),
        new("safety_reflection_priority", "Du findest, wie Menschen behandelt werden und ob ein Team sich sicher fühlt, ehrlich zu sein, sind grundlegende Themen für Reflexion. Probleme, die eine unsichere Kultur verbirgt, sind am schwersten zu beheben — bis sie auftauchen, haben sie meist schon Schaden angerichtet."),
    };

